// Injected by Millennium into Steam's browser views. core.js is generated by scripts/build.mjs.
import { pluginConfig, subscribePluginConfig } from "millennium";
import "./core.js";

const CACHE_KEY = "unslopCache";
const SETTINGS_KEY = "unslopSettings";

// The settings live in Millennium's plugin config, shared with the panel in Millennium's settings.
const PLUGIN_NAME = "steam-unslop";
const CONFIG_KEY = "settings";

type Cache = Record<string, { t: number }>;

function loadLocal(key: string): unknown {
  try {
    return JSON.parse(localStorage.getItem(key) || "null");
  } catch {
    return null;
  }
}

// Quota exceeded: drop the older half of the cache and retry once.
function saveSmallerCache(cache: Cache) {
  const entriesByAge = Object.entries(cache).sort(([, first], [, second]) => first.t - second.t);
  entriesByAge.slice(0, entriesByAge.length >> 1).forEach(([appId]) => delete cache[appId]);

  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify(cache));
  } catch {
    // Give up.
  }
}

function saveLocal(key: string, value: unknown) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    if (key === CACHE_KEY && value && typeof value === "object") saveSmallerCache(value as Cache);
  }
}

async function loadSettings(): Promise<unknown> {
  try {
    return (await pluginConfig.get(PLUGIN_NAME, CONFIG_KEY)) ?? loadLocal(SETTINGS_KEY);
  } catch {
    return loadLocal(SETTINGS_KEY);
  }
}

const storage = {
  load: async (key: string): Promise<unknown> =>
    key === SETTINGS_KEY ? loadSettings() : loadLocal(key),

  save: async (key: string, value: unknown) => {
    saveLocal(key, value);
    if (key === SETTINGS_KEY) pluginConfig.set(PLUGIN_NAME, CONFIG_KEY, value).catch(() => {});
  },

  remove: async (keys: string[]) => keys.forEach(key => localStorage.removeItem(key)),
};

export default async function main() {
  if (location.hostname !== "store.steampowered.com" || window.top !== window) return;

  const steamUnslop = (globalThis as any).SteamUnslop;
  steamUnslop.hold();

  // Results, rate limits and settings from other Steam windows.
  addEventListener("storage", event => {
    if (!event.key || !event.newValue) return;

    try {
      steamUnslop.applyStored(event.key, JSON.parse(event.newValue));
    } catch {
      // Not ours.
    }
  });

  // Changes made in the settings panel.
  try {
    subscribePluginConfig(PLUGIN_NAME, (key: string, value: unknown) => {
      if (key === CONFIG_KEY) steamUnslop.applyStored(SETTINGS_KEY, value);
    });
  } catch {
    // Older Millennium without plugin config.
  }

  if (document.readyState === "loading") {
    await new Promise(resolve =>
      document.addEventListener("DOMContentLoaded", resolve, { once: true }),
    );
  }
  steamUnslop.start(storage);
}
